import { chromium } from "playwright";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

// The public registry is generated by PHP in the workflow, not hand-maintained.
const registered = JSON.parse(readFileSync(process.argv[2] || "visual-qa/public-routes.json", "utf8"));
if (!Array.isArray(registered)) throw Error("Expected Pages registry paths array.");
const routes = registered.filter(path => path !== "" && path !== "contact");
mkdirSync("visual-qa/interiors", {recursive:true});
const widths = [["desktop-1440",1440,900],["mobile-390",390,844]];
const evidence = {commit:process.env.GITHUB_SHA,routes:routes.length,results:[],failures:[]};
const browser = await chromium.launch({headless:true});
try {
  for (const [viewport,width,height] of widths) {
    const context = await browser.newContext({viewport:{width,height},deviceScaleFactor:1,reducedMotion:"reduce"});
    const page = await context.newPage();
    const jsErrors=[];
    page.on("pageerror",error=>jsErrors.push(error.message));
    mkdirSync("visual-qa/interiors/"+viewport,{recursive:true});
    for (const slug of routes) {
      const url="http://127.0.0.1:8000/en/"+slug;
      jsErrors.length=0;
      const response=await page.goto(url,{waitUntil:"domcontentloaded",timeout:45000});
      await page.locator(".umi-mockup .umi-interior .umi-interior-hero").waitFor({timeout:10000}).catch(()=>{});
      await page.evaluate(()=>document.fonts.ready);
      await page.evaluate(async()=>{
        for(let y=0;y<document.documentElement.scrollHeight;y+=850) {
          window.scrollTo(0,y);
          await new Promise(resolve=>setTimeout(resolve,15));
        }
        window.scrollTo(0,0);
      });
      await page.waitForTimeout(90);
      const details=await page.evaluate(()=>{
        const r=document.querySelector("header .umi-engineering-ruler")?.getBoundingClientRect();
        return {
          title:document.title,
          heading:document.querySelector("main h1")?.textContent?.trim() ?? null,
          language:document.documentElement.lang,
          shell:!!document.querySelector(".umi-mockup"),
          interior:!!document.querySelector(".umi-interior"),
          hero:!!document.querySelector(".umi-interior-hero"),
          ruler:r?{x:Math.round(r.x),y:Math.round(r.y),width:Math.round(r.width),height:Math.round(r.height)}:null,
          footer:!!document.querySelector(".umi-mockup footer"),
          sectionCount:document.querySelectorAll(".umi-interior .umi-content-band").length,
          missingImages:Array.from(document.images).filter(img=>img.loading!=="lazy"&&(!img.complete||img.naturalWidth===0)).map(img=>img.currentSrc),
          horizontalOverflow:document.documentElement.scrollWidth>window.innerWidth+2,
        };
      });
      const file=join("visual-qa/interiors",viewport,slug.replaceAll("/","__")+".jpg");
      await page.screenshot({path:file,fullPage:true,animations:"disabled",type:"jpeg",quality:77});
      const item={route:"/en/"+slug,viewport,status:response?.status(),file,...details,errors:jsErrors.slice()};
      evidence.results.push(item);
      if(response?.status()!==200||!details.shell||!details.interior||!details.hero||
          !details.ruler||!details.footer||!details.heading||details.horizontalOverflow||
          jsErrors.length||details.missingImages.length)evidence.failures.push(item);
    }
    await context.close();
  }
  const context=await browser.newContext({viewport:{width:1440,height:900}});
  const page=await context.newPage();
  await page.goto("http://127.0.0.1:8000/en/products",{waitUntil:"domcontentloaded"});
  const destinations=await page.locator('.umi-interior-cards a[href*="/products/"]').evaluateAll(
    nodes=>nodes.map(node=>node.getAttribute("href"))
  );
  const malformed=destinations.filter(href=>!/^\/en\/products\/[^/]+$/.test(href??""));
  evidence.productLinks={tested:destinations.length,urls:destinations,malformed};
  if(malformed.length||destinations.length===0)evidence.failures.push({productLinks:evidence.productLinks});
  await context.close();
} finally {await browser.close();}
writeFileSync("visual-qa/interiors/route-report.json",JSON.stringify(evidence,null,2));
console.log(JSON.stringify({routes:evidence.routes,viewportChecks:evidence.results.length,
  failures:evidence.failures.length,productLinks:evidence.productLinks},null,2));
if(evidence.failures.length)process.exitCode=1;
